import SwiftUI

/// The crisis screen. Its wording and resources are fixed here, never generated by the model. Resources must be
/// verified and kept current by people before release; regions other than the US get the international helpline
/// directory and the local emergency number. Order: the most urgent options first as large tap targets, then a
/// grounding exercise, then the disclaimer. Resources are solid content cards, not glass, so they read instantly.
struct CrisisView: View {
    @Environment(\.locale) private var locale
    @Environment(\.dismiss) private var dismiss

    private var isUS: Bool { locale.region?.identifier == "US" }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: Theme.Spacing.screen) {
                    VStack(alignment: .leading, spacing: Theme.Spacing.small) {
                        Text("You don't have to go through this alone.")
                            .font(.title.bold())
                            .accessibilityAddTraits(.isHeader)
                        Text("If you might act on thoughts of harming yourself or someone else, please reach out to someone now.")
                            .font(.title3)
                            .foregroundStyle(.secondary)
                    }

                    if isUS {
                        USCrisisResources()
                    } else {
                        InternationalCrisisResources()
                    }

                    VStack(alignment: .leading, spacing: Theme.Spacing.medium) {
                        Text("A moment to ground yourself")
                            .font(.title3.bold())
                            .accessibilityAddTraits(.isHeader)
                        BreathingExercise()
                        Text("Breathe in slowly for 4 counts, hold for 4, out for 6. Then name 5 things you can see, 4 you can touch, 3 you can hear, 2 you can smell and 1 you can taste.")
                            .foregroundStyle(.secondary)
                    }

                    Label("Companion is not a therapist or an emergency service, and it can't contact anyone for you.",
                          systemImage: "info.circle")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
                .padding(.horizontal, Theme.Spacing.large)
                .padding(.vertical, Theme.Spacing.small)
                .frame(maxWidth: Theme.readableWidth)
                .frame(maxWidth: .infinity)
            }
            .background(AppBackground())
            .navigationTitle("Support")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    // a spelled-out label rather than an X: someone in distress should never have to guess
                    Button("Back to chat", action: close)
                }
            }
        }
        .presentationDragIndicator(.visible)
    }

    private func close() {
        dismiss()
    }
}

#Preview("US") {
    CrisisView()
        .environment(\.locale, Locale(identifier: "en_US"))
}

#Preview("Elsewhere") {
    CrisisView()
        .environment(\.locale, Locale(identifier: "en_GB"))
}
